  $demo$::jsonb) AS r
),
mapped AS (
  SELECT r
    || jsonb_build_object(
         'primary_user_id', (SELECT p.id::text FROM public.profiles p WHERE trim(p.full_name) = src.r->>'primary_user' LIMIT 1),
         'appointment_type_id', (SELECT t.id::text FROM public.appointment_types t WHERE t.name = src.r->>'appointment_type_name' LIMIT 1),
         'created_at', now(),
         'updated_at', now()
       )
    || jsonb_strip_nulls(jsonb_build_object(
         'patient_id', (SELECT ap.id::text FROM public.all_patients ap WHERE ap.name = src.r->>'patient_name' ORDER BY ap.id LIMIT 1)
       )) AS r
  FROM src
)
INSERT INTO public.appointments
SELECT (jsonb_populate_record(NULL::public.appointments, m.r)).*
FROM mapped m
WHERE NOT EXISTS (
  SELECT 1 FROM public.appointments a
  WHERE a.id::text = m.r->>'id'
     OR (a.primary_user = m.r->>'primary_user'
         AND a.date = m.r->>'date'
         AND a.time_start = m.r->>'time_start'
         AND a.patient_name IS NOT DISTINCT FROM m.r->>'patient_name')
);

-- 2. User availability (Abhijit Gupta, Abhay Chaudhary).
INSERT INTO public.user_availability
SELECT (jsonb_populate_record(NULL::public.user_availability,
  r || jsonb_build_object(
    'user_id', (SELECT p.id::text FROM public.profiles p WHERE trim(p.full_name) = r->>'user_name' LIMIT 1),
    'created_at', now(),
    'updated_at', now()
  ))).*
FROM jsonb_array_elements($demo$
